  b09TpuUlx: { t: 'TechPowerUp, Finalmouse UltralightX review: polling 500/1000 Hz wired, up to 4000 Hz wireless at launch (8000 Hz by a later update)', u: 'https://techpowerup.com/review/finalmouse-ultralightx/single-page.html' },
  b09TpuMchose: { t: 'TechPowerUp, MCHOSE AX5 Pro Max review: two microcontrollers, a WCH CH32V305 ("provides a USB high-speed PHY") and a Nordic nRF52840; 8000 Hz wired and wireless', u: 'https://techpowerup.com/review/mchose-ax5-pro-max/single-page.html' },
  b09RazerV3: { t: 'Razer Insider, Razer staff on the Viper V3 Pro: "To achieve the higher polling rates, including 2000Hz and up to 8000Hz", use the HyperPolling Wireless Dongle (the cable stops at 1000 Hz)', u: 'https://insider.razer.com/razer-support-45/razer-viper-v3-pro-polling-rate-is-limited-to-1000hz-75006' },
  b09TweakV4: { t: 'TweakTown, Razer Viper V4 Pro review: 8,000 Hz "across both wired and wireless modes"; up to 180 h at 1000 Hz, 45 h at 8000 Hz', u: 'https://www.tweaktown.com/reviews/11398/razer-viper-v4-pro-wireless-gaming-mouse-built-for-competition/index.html' },
  b09Iowa: { t: 'University of Iowa physics lecture demonstrations, 5B20.35 "Faraday\'s Cage - Radio": a phone wrapped in foil (in a plastic bag) does not ring', u: 'https://instructional-resources.physics.uiowa.edu/node/5366' },
  b09GearPatrol: { t: 'Gear Patrol (Eric Limer, 2024-12-01): radio waves pass plastic but "are blocked by materials that do [conduct electricity] (like metal)": why metal phones carry plastic antenna lines', u: 'https://www.gearpatrol.com/tech/iphone-antenna-lines-explained' },
  b09RaytacMdbt: { t: 'Raytac MDBT50Q specification, ver. K, 2.3 RF layout: no ground under the antenna on every layer; place the module toward the board edge', u: 'https://cdn.sparkfun.com/assets/4/7/4/3/8/_nRF52840__MDBT50Q-1MV2___MDBT50Q-P1MV2_Ver.K_spec.pdf' },
