/* ============================== 6. b09_sync: frame sync, 202 → 42 µs ============================== */
/** one row of the frame-sync demonstration. The hand moves at a steady speed, so the track is both its path and time
   (µs). Reports leave every 125 µs (polls); at each one the cursor jumps to where the hand was when the frame it carries
   was taken. frameOf(k) gives that frame's time for poll k; flashes (optional) are the camera's own frames, drawn as small
   ticks over the track. Under the track, one bar per report: how far it moved the cursor (even bars: smooth; uneven:
   stutter). g = { x, y, w, us (track length, µs), tStart, rate (µs per slide-second), col, a, flashes, gap (shade the lag),
   lagLabel }. Returns { ages } (the age of each report sent so far) */
function b09_syncRow(t, g, frameOf) {
  const a = g.a == null ? 1 : g.a, X = us => g.x + us / g.us * g.w, tau = clamp((t - g.tStart) * g.rate, 0, g.us), y = g.y;
  const out = { ages: [] };
  if (a <= 0.003) return out;
  line(X(0), y, X(g.us), y, { color: C.hair, w: 2, alpha: a });
  /* the camera's own frames: a tick each as the hand passes it (the unsynced row) */
  if (g.flashes) for (let f = 0; f <= g.us; f += g.flashes) { if (f > tau) break; line(X(f), y - 22, X(f), y - 8, { color: C.mute, w: 2, alpha: a }); }
  /* the polls: a tick under the track every 125 µs */
  const P = [], steps = [];
  for (let k = 1; k * 125 <= g.us; k++) {
    const p = k * 125; line(X(p), y + 8, X(p), y + 20, { color: inkA(0.4), w: 2, alpha: a });
    if (p > tau) continue;
    const f = frameOf(k); if (f < 0) continue;
    if (P.length) steps.push([X(p), f - P[P.length - 1].f]);
    P.push({ x: X(f), f }); out.ages.push(p - f);
  }
  if (P.length > 1) poly(P.map(q => [q.x, y]), { color: g.col, w: 5, alpha: a });
  P.forEach(q => circle(q.x, y, 8, { fill: g.col, alpha: a }));
  /* how far each report moved the cursor: one bar per report, under the track */
  const bh = 0.36;                                            /* px of bar per µs of motion */
  steps.forEach(([xp, st]) => rr(xp - 9, y + 92 - st * bh, 18, st * bh, 3, g.col, null, 1, a * 0.85));
  if (steps.length) line(X(0), y + 92, X(g.us), y + 92, { color: C.hair, w: 1.5, alpha: a });
  /* the hand, a ring at its true place; the cursor, an arrow at the last report's place; the lag between them shaded */
  if (tau > 0) {
    circle(X(tau), y, 15, { color: inkA(0.6), w: 2.5, alpha: a });
    if (P.length) {
      const c = P[P.length - 1].x;
      if (g.gap) rect(c, y - 6, X(tau) - c, 12, { fill: rgba(g.col, 0.25), alpha: a });
      cursorPtr(c + 1, y + 1, { a, s: 1.05 });
      if (g.lagLabel && tau >= g.us) text(g.lagLabel, (c + X(tau)) / 2, y - 26, { role: 'label', size: 20, color: g.lagCol || g.col, align: 'center', alpha: a });
    }
  }
  return out;
}
